<template>
  <div class="overview-page">
    <div class="overview-head"><div><span class="eyebrow">运营中心 / 实时概览</span><h2>今天，平台运行得怎么样？</h2><p>关键数据、服务状态和最近活动都集中在这里。</p></div><t-button variant="outline" :loading="loading" @click="load"><template #icon><t-icon name="refresh" /></template>刷新数据</t-button></div>
    <t-alert v-if="loadError" theme="error" :message="loadError" style="margin-bottom:16px" /><div class="metric-grid"><article class="metric-card accent-orange"><span class="metric-icon">人</span><div><small>注册用户</small><strong>{{ stats.users }}</strong><em>全部账号</em></div></article><article class="metric-card accent-violet"><span class="metric-icon">✦</span><div><small>平台积分余额</small><strong>{{ formatNumber(stats.total_points) }}</strong><em>当前用户余额合计</em></div></article><article class="metric-card accent-blue"><span class="metric-icon">¥</span><div><small>累计收款</small><strong>¥{{ Number(stats.revenue || 0).toFixed(2) }}</strong><em>{{ stats.paid_orders || 0 }} 笔已支付订单</em></div></article><article class="metric-card accent-green"><span class="metric-icon">✓</span><div><small>待处理任务</small><strong class="status-text">{{ stats.running_tasks || 0 }}</strong><em>{{ stats.pending_orders || 0 }} 笔订单待支付</em></div></article></div>
    <div class="overview-columns"><section class="surface activity-panel"><div class="surface-head"><div><h3>最近活动</h3><p>最新的积分流水与平台操作</p></div><button class="text-btn" @click="go('points')">查看全部 <span>→</span></button></div><div v-if="logs.length" class="activity-list"><div v-for="log in logs.slice(0,6)" :key="log.id" class="activity-item"><span class="activity-dot" :class="log.type"></span><div><strong>{{ log.user_name || '系统用户' }}</strong><span>{{ log.action || typeText(log.type) }}</span></div><b :class="Number(log.amount) < 0 ? 'negative' : 'positive'">{{ Number(log.amount) > 0 ? '+' : '' }}{{ log.amount }}</b><time>{{ formatTime(log.created_at) }}</time></div></div><t-empty v-else description="暂无活动记录" /></section><section class="surface quick-panel"><div class="surface-head"><div><h3>快捷操作</h3><p>常用的管理入口</p></div></div><button class="quick-action" @click="go('users')"><span class="quick-icon orange">♙</span><span><b>管理用户</b><small>角色、状态与账号</small></span><i>→</i></button><button class="quick-action" @click="go('points')"><span class="quick-icon blue">◇</span><span><b>分配积分</b><small>充值、赠送与流水</small></span><i>→</i></button><button class="quick-action" @click="go('pricing')"><span class="quick-icon violet">◈</span><span><b>调整计费</b><small>模型倍率与价格规则</small></span><i>→</i></button><button class="quick-action" @click="go('settings')"><span class="quick-icon green">⚙</span><span><b>系统设置</b><small>平台策略与安全</small></span><i>→</i></button></section></div>
    <section class="surface health-panel"><div class="surface-head"><div><h3>平台健康度</h3><p>最近一次数据更新：{{ lastUpdated || '尚未成功' }}</p></div><span>{{ loadError ? '获取失败' : loading ? '正在获取' : '数据已加载' }}</span></div><div class="health-grid"><div v-for="item in health" :key="item.name" class="health-item"><span class="health-check">✓</span><div><b>{{ item.name }}</b><small>{{ item.detail }}</small></div><strong>{{ item.value }}</strong></div></div></section>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import axios from '@/utils/axios';
const loading=ref(false); const stats=ref<any>({users:0,total_points:0,consumed_points:0,revenue:0,paid_orders:0,pending_orders:0,running_tasks:0}); const logs=ref<any[]>([]);
const loadError = ref(''), lastUpdated = ref('');
const health = computed(() => [
 { name:'管理接口', detail:'仅代表最近一次概览请求', value:loadError.value ? '获取失败' : lastUpdated.value ? '请求成功' : '待查询' },
 { name:'任务中心', detail:'已入库的进行中任务', value:lastUpdated.value ? String(stats.value.running_tasks || 0) + ' 条' : '待查询' },
 { name:'上游模型', detail:'可在供应商配置中主动测试', value:'未检测' },
]);
function formatNumber(n:number){return new Intl.NumberFormat('zh-CN').format(Number(n||0));}
function formatTime(v:string){if(!v)return '-'; const d=new Date(v); return Number.isNaN(d.getTime())?v:`${d.getMonth()+1}月${d.getDate()}日 ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function typeText(v:string){return ({consume:'消费积分',recharge:'充值积分',gift:'赠送积分',refund:'退回积分'} as any)[v]||'积分变更';}
function go(tab:string){window.dispatchEvent(new CustomEvent('admin:navigate',{detail:tab}));}
async function load(){if(loading.value)return;loading.value=true;loadError.value=""; try{const [a,b]=await Promise.all([axios.get('/setting/pointsConfig/admin/dashboard'),axios.get('/setting/pointsConfig/admin/recentLogs?limit=8')]); stats.value=a.data||{}; logs.value=b.data||[];lastUpdated.value=new Date().toLocaleString('zh-CN');}catch(e){loadError.value='数据加载失败；已显示的数据可能已过期，请重试';}finally{loading.value=false;}}
onMounted(load);
</script>
<style scoped lang="scss">
